from typing import Sequence


def char_stats(text: str, chars: Sequence[str], case_sensitive: bool = False) -> dict:
    """Count the given characters in any string."""
    for c in chars:
        if len(c) != 1:
            raise ValueError(f"each entry must be a single character, got {c!r}")
    haystack = text if case_sensitive else text.lower()
    per_char = {}
    for c in dict.fromkeys(chars):
        needle = c if case_sensitive else c.lower()
        positions = [i for i, ch in enumerate(haystack) if ch == needle]
        per_char[c] = {"count": len(positions), "positions": positions,
                       "share": round(len(positions) / len(text), 4) if text else 0.0}
    total = sum(v["count"] for v in per_char.values())
    return {"length": len(text), "total_matches": total,
            "match_share": round(total / len(text), 4) if text else 0.0, "chars": per_char}

