import pytest
from solution import char_stats


def test_strawberry():
    assert char_stats("strawberry", ["r"])["chars"]["r"]["count"] == 3


def test_positions():
    assert char_stats("strawberry", ["r"])["chars"]["r"]["positions"] == [2, 7, 8]


def test_case_insensitive_by_default():
    assert char_stats("Mississippi", ["m", "S"])["total_matches"] == 5


def test_case_sensitive():
    assert char_stats("Mississippi", ["m"], case_sensitive=True)["chars"]["m"]["count"] == 0


def test_empty_text():
    assert char_stats("", ["a"])["match_share"] == 0.0


def test_rejects_multi_character_entries():
    with pytest.raises(ValueError):
        char_stats("abc", ["ab"])
